{
  "sections": {
    "main": {
      "type": "main-collection",
      "blocks": {
        "filters": {
          "type": "filters",
          "static": true,
          "settings": {
            "enable_filtering": true,
            "filter_style": "horizontal",
            "filter_width": "centered",
            "text_label_case": "default",
            "show_swatch_label": false,
            "show_filter_label": true,
            "enable_sorting": true,
            "enable_grid_density": true,
            "inherit_color_scheme": true,
            "color_scheme": "",
            "padding-block-start": 8,
            "padding-block-end": 8,
            "padding-inline-start": 0,
            "padding-inline-end": 0,
            "facets_margin_bottom": 8,
            "facets_margin_right": 20
          },
          "blocks": {}
        },
        "product-card": {
          "type": "_product-card",
          "static": true,
          "settings": {
            "product_card_gap": 4,
            "inherit_color_scheme": true,
            "color_scheme": "",
            "border": "none",
            "border_width": 1,
            "border_opacity": 100,
            "border_radius": 0,
            "padding-block-start": 0,
            "padding-block-end": 0,
            "padding-inline-start": 0,
            "padding-inline-end": 0
          },
          "blocks": {
            "card-gallery": {
              "type": "_product-card-gallery",
              "settings": {
                "image_ratio": "portrait",
                "border": "none",
                "border_width": 1,
                "border_opacity": 100,
                "border_radius": 0,
                "padding-block-start": 0,
                "padding-block-end": 0,
                "padding-inline-start": 0,
                "padding-inline-end": 0
              },
              "blocks": {}
            },
            "product_title_4nY4eT": {
              "type": "product-title",
              "name": "t:names.product_title",
              "settings": {
                "width": "100%",
                "max_width": "normal",
                "alignment": "left",
                "type_preset": "rte",
                "font": "var(--font-body--family)",
                "font_size": "1rem",
                "line_height": "normal",
                "letter_spacing": "normal",
                "case": "none",
                "wrap": "pretty",
                "color": "var(--color-foreground)",
                "background": false,
                "background_color": "#00000026",
                "corner_radius": 0,
                "padding-block-start": 4,
                "padding-block-end": 0,
                "padding-inline-start": 0,
                "padding-inline-end": 0
              },
              "blocks": {}
            },
            "price_EzJzMm": {
              "type": "price",
              "settings": {
                "show_sale_price_first": true,
                "show_installments": false,
                "show_tax_info": false,
                "type_preset": "h6",
                "width": "100%",
                "alignment": "left",
                "font": "var(--font-body--family)",
                "font_size": "1rem",
                "line_height": "normal",
                "letter_spacing": "normal",
                "case": "none",
                "color": "var(--color-foreground)",
                "padding-block-start": 0,
                "padding-block-end": 0,
                "padding-inline-start": 0,
                "padding-inline-end": 0
              },
              "blocks": {}
            }
          },
          "block_order": [
            "card-gallery",
            "product_title_4nY4eT",
            "price_EzJzMm"
          ]
        }
      },
      "custom_css": [],
      "settings": {
        "layout_type": "grid",
        "product_card_size": "medium",
        "mobile_product_card_size": "small",
        "enable_infinite_scroll": true,
        "products_per_page": 24,
        "product_grid_width": "centered",
        "full_width_on_mobile": true,
        "columns_gap_horizontal": 16,
        "columns_gap_vertical": 32,
        "padding-inline-start": 0,
        "padding-inline-end": 0,
        "color_scheme": "scheme-1",
        "padding-block-start": 0,
        "padding-block-end": 32
      }
    },
    "lux_faq": {
      "type": "custom-liquid",
      "settings": {
        "custom_liquid": "<div style="max-width:820px;margin:0 auto;font-size:15px;line-height:1.6;color:#333"><h2 style="font-size:20px;margin:0 0 6px">Häufige Fragen zu {{ collection.title }}</h2><p style="color:#666;margin:0 0 8px">Alles rund um {{ collection.title }} bei LuxeStyle – kuratierte Auswahl, faire Preise, Lieferdatum beim Artikel und in der Kasse.</p><details style="border-top:1px solid #ececec;padding:11px 0"><summary style="cursor:pointer;font-weight:600;list-style:none">🚚 Wie lange dauert der Versand in die Schweiz?</summary><p style="margin:8px 0 0;color:#555">Ab Schweizer Lager meist 2–3 Werktage, im Direktversand 10–20 Werktage; das genaue Datum steht beim Artikel und in der Kasse — immer mit Sendungsverfolgung. Gratis-Versand ab CHF 50 nach Rabatt, sonst CHF 7.00.</p></details><details style="border-top:1px solid #ececec;padding:11px 0"><summary style="cursor:pointer;font-weight:600;list-style:none">💳 Welche Zahlungsmethoden gibt es?</summary><p style="margin:8px 0 0;color:#555">TWINT, Visa, Mastercard und weitere – sicher und SSL-verschlüsselt.</p></details><details style="border-top:1px solid #ececec;padding:11px 0"><summary style="cursor:pointer;font-weight:600;list-style:none">↩️ Wie funktioniert die Rückgabe?</summary><p style="margin:8px 0 0;color:#555">Wir gewähren ein freiwilliges 30-Tage-Rückgaberecht. Eine kurze Nachricht an info@luxestyle.ch genügt.</p></details><details style="border-top:1px solid #ececec;padding:11px 0"><summary style="cursor:pointer;font-weight:600;list-style:none">📏 Wie finde ich die richtige Grösse?</summary><p style="margin:8px 0 0;color:#555">Bei Mode- und Schuh-Artikeln findest du eine cm-Grössentabelle direkt auf der jeweiligen Produktseite.</p></details><details style="border-top:1px solid #ececec;padding:11px 0"><summary style="cursor:pointer;font-weight:600;list-style:none">🇨🇭 Warum bei LuxeStyle kaufen?</summary><p style="margin:8px 0 0;color:#555">Schweizer Online-Shop mit kuratierter Auswahl, fairen Preisen, sicherer Zahlung und persönlichem Support auf Deutsch.</p></details></div>",
        "section_width": "page-width",
        "padding-block-start": 28,
        "padding-block-end": 28
      }
    },
    "lux_breadcrumb": {
      "type": "custom-liquid",
      "settings": {
        "custom_liquid": "{%- liquid
  assign p_title = ''
  assign p_url = ''
  for link in linklists.main-menu.links
    for sub in link.links
      if sub.url == collection.url and p_title == ''
        assign p_title = link.title
        assign p_url = link.url
      endif
      for sub2 in sub.links
        if sub2.url == collection.url and p_title == ''
          assign p_title = sub.title
          assign p_url = sub.url
        endif
      endfor
    endfor
  endfor
-%}
<nav aria-label="Breadcrumb" style="max-width:var(--page-width,1200px);margin:0 auto;padding:.4rem 1.5rem 0;font-size:.95rem;font-weight:600;line-height:1.4;color:#3d2f18;display:flex;flex-wrap:wrap;gap:.3rem;align-items:center;">
  <a href="{{ routes.root_url }}" style="color:#6b4f1d;font-weight:700;text-decoration:none;">Home</a>
  {%- if p_title != blank %}<span aria-hidden="true">&rsaquo;</span>
  <a href="{{ p_url }}" style="color:#6b4f1d;font-weight:700;text-decoration:none;">{{ p_title | strip }}</a>{% endif -%}
  <span aria-hidden="true">&rsaquo;</span>
  <span aria-current="page" style="color:#1f1a12;font-weight:700;">{{ collection.title }}</span>
</nav>
<script type="application/ld+json">
{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[
{"@type":"ListItem","position":1,"name":"Home","item":"{{ shop.url }}{{ routes.root_url }}"}{%- if p_title != blank %},
{"@type":"ListItem","position":2,"name":{{ p_title | strip | json }},"item":"{{ shop.url }}{{ p_url }}"},
{"@type":"ListItem","position":3,"name":{{ collection.title | json }},"item":"{{ shop.url }}{{ collection.url }}"}{% else %},
{"@type":"ListItem","position":2,"name":{{ collection.title | json }},"item":"{{ shop.url }}{{ collection.url }}"}{% endif -%}
]}
</script>
",
        "padding-block-start": 0,
        "padding-block-end": 0
      }
    },
    "lux_subchips": {
      "type": "custom-liquid",
      "settings": {
        "custom_liquid": "{%- liquid
  assign chips = ''
  for link in linklists.main-menu.links
    if link.url == collection.url and link.links.size > 1
      assign chips = link.links
    endif
    for sub in link.links
      if sub.url == collection.url and link.links.size > 1
        assign chips = link.links
      endif
    endfor
  endfor
-%}
{%- if chips != '' and chips.size > 1 -%}
{%- assign lx_max = 7 -%}
{%- assign lx_n = chips.size -%}
<nav class="lx-tabs" aria-label="Unterkategorien">
<style>
.lx-tabs{max-width:min(var(--page-width,1200px),100%);width:100%;min-width:0;margin:0 auto;padding:.5rem 1.5rem .2rem;box-sizing:border-box}
.lx-tabs__zeile{display:flex;flex-wrap:wrap;align-items:baseline;gap:.2rem 1.7rem;border-bottom:1px solid #cdbd9f;padding:0 0 .1rem;margin:0;list-style:none}
.lx-tabs a,.lx-tabs summary{font-size:.9rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase;text-decoration:none;color:#2f2414;padding:.45rem 0;border-bottom:2px solid transparent;transition:color .35s ease,border-color .35s ease;display:inline-block}
.lx-tabs a:hover{color:#1f1a12;border-bottom-color:#cdbd9f}
.lx-tabs a[aria-current="page"]{color:#1f1a12;font-weight:800;border-bottom-color:#8b7355;border-bottom-width:3px}
.lx-tabs summary{list-style:none;cursor:pointer;color:#6b4f1d;font-weight:700}
.lx-tabs summary::-webkit-details-marker{display:none}
.lx-tabs summary::after{content:' ▾'}
.lx-tabs details[open] summary::after{content:' ▴'}
.lx-tabs__alle{list-style:none;margin:.35rem 0 .2rem;padding:.9rem 0 .5rem;columns:13.5rem;column-gap:2rem;border-bottom:1px solid #e8e1d4}
.lx-tabs__alle li{break-inside:avoid}
.lx-tabs__alle a{letter-spacing:.04em;text-transform:none;font-size:.88rem;display:block;padding:.3rem 0}
@media(max-width:749px){.lx-tabs__zeile{flex-wrap:nowrap;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;gap:1.3rem}.lx-tabs__zeile>li{flex:0 0 auto}}
</style>
<ul class="lx-tabs__zeile">
  {%- for ch in chips -%}
    {%- if forloop.index <= lx_max or ch.url == collection.url -%}
      <li><a href="{{ ch.url }}"{% if ch.url == collection.url %} aria-current="page"{% endif %}>{{ ch.title }}</a></li>
    {%- endif -%}
  {%- endfor -%}
</ul>
{%- if lx_n > lx_max -%}
<details class="lx-tabs__details" style="margin:0"><summary style="margin:.2rem 0 0;display:inline-block">Alle {{ lx_n }} Kategorien</summary>
<ul class="lx-tabs__alle">
  {%- for ch in chips -%}<li><a href="{{ ch.url }}"{% if ch.url == collection.url %} aria-current="page"{% endif %}>{{ ch.title }}</a></li>{%- endfor -%}
</ul></details>
{%- endif -%}
</nav>
{%- endif -%}
{%- liquid
  assign lx_uf = collection.metafields.lux.unterfilter.value
  assign lx_kopf = collection
  if lx_uf == blank
    assign lx_el = collection.metafields.lux.eltern.value
    if lx_el != blank
      assign lx_uf = lx_el.metafields.lux.unterfilter.value
      assign lx_kopf = lx_el
    endif
  endif
-%}
{%- if lx_uf != blank and lx_uf.size > 0 -%}
<nav class="lx-uf" aria-label="Unterfilter {{ lx_kopf.title | escape }}">
<style>.lx-uf{max-width:min(var(--page-width,1200px),100vw);margin:0 auto;padding:.35rem 1.5rem .2rem;box-sizing:border-box}.lx-uf__zeile{display:flex;gap:.45rem;align-items:center;flex-wrap:wrap}.lx-uf__label{font-size:.9rem;font-weight:700;color:#3d2f18;white-space:nowrap}.lx-uf a{white-space:nowrap;font-size:.92rem;font-weight:600;padding:.4rem .95rem;border-radius:999px;text-decoration:none;border:1px solid #bfae8c;background:#fff;color:#2f2414;transition:background .35s ease,border-color .35s ease,color .35s ease}.lx-uf a:hover{border-color:#8b7355;color:#1f1a12}.lx-uf a[aria-current="page"]{background:#8b7355;border-color:#8b7355;color:#fff;font-weight:600}@media(max-width:749px){.lx-uf__zeile{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;padding-bottom:.3rem}.lx-uf__zeile::-webkit-scrollbar{display:none}}</style>
  <div class="lx-uf__zeile">
    <span class="lx-uf__label">{{ lx_kopf.title | escape }}:</span>
    <a href="{{ lx_kopf.url }}"{% if lx_kopf.id == collection.id %} aria-current="page"{% endif %}>Alle</a>
    {%- for f in lx_uf -%}<a href="{{ f.url }}"{% if f.id == collection.id %} aria-current="page"{% endif %}>{{ f.title | escape }}</a>{%- endfor -%}
  </div>
</nav>
{%- endif -%}
{%- comment -%}
  Filterzeile (30.08.2026): native Tag-Filterung — auf Kollektionen ueber 5000
  Produkten schaltet Shopify die Facetten hart ab (Plattform-Limit); Tags kennen kein Limit. Tag-Liste GEMESSEN
  (productsCount je Tag) — neue Tags nur mit Zahl dahinter ergaenzen.
{%- endcomment -%}
{%- liquid
  assign welt = ''
  assign menuetitel = ''
  for link in linklists.main-menu.links
    if link.url == collection.url
      assign welt = link.title
    endif
    for sub in link.links
      if sub.url == collection.url and welt == ''
        assign welt = link.title
      endif
      for sub2 in sub.links
        if sub2.url == collection.url and welt == ''
          assign welt = link.title
        endif
      endfor
    endfor
  endfor
  for ch in chips
    assign menuetitel = menuetitel | append: '|' | append: ch.title | downcase
  endfor
  comment
    Welt-Whitelist (05.09.2026, Audit kategorie-navigation): «Jacken» auf Wohnen fuehrte zu 1 Hundejacke,
    «Ringe» auf Elektronik zu Smartwatches mit «Monitoring» — collection.all_tags kennt keine Stueckzahl.
    Je Welt nur die Tags, die dort etwas bedeuten; ohne erkannte Welt gilt die volle Liste.
  endcomment
  case welt
    when 'Damen'
      assign erlaubt = 'neu,damen,kleid,jacke,pullover,hemd,schuhe,sneaker,stiefel,guertel,taschen,rucksack,schmuck,uhren,sport,geschenk,ch-lager'
    when 'Herren'
      assign erlaubt = 'neu,herren,jacke,pullover,hemd,schuhe,sneaker,stiefel,guertel,taschen,rucksack,uhren,sport,geschenk,ch-lager'
    when 'Schuhe'
      assign erlaubt = 'neu,damen,herren,kinder,sneaker,stiefel,sport,ch-lager'
    when 'Schmuck & Uhren'
      assign erlaubt = 'neu,damen,herren,halskette,armband,ring,uhren,geschenk,ch-lager'
    when 'Beauty & Parfüm'
      assign erlaubt = 'neu,damen,herren,beauty,hautpflege,naegel,geschenk,ch-lager'
    when 'Wohnen & Garten'
      assign erlaubt = 'neu,wohnen,kueche,aufbewahrung,kissen,werkzeug,geschenk,ch-lager'
    when 'Technik & Gaming'
      assign erlaubt = 'neu,elektronik,gadget,ladegeraet,gaming,auto,uhren,geschenk,ch-lager'
    when 'Kinder & Haustier'
      assign erlaubt = 'neu,kinder,baby,spielzeug,haustier,schuhe,geschenk,ch-lager'
    when 'Sport & Party'
      assign erlaubt = 'neu,sport,kostuem,halloween,damen,herren,kinder,geschenk,ch-lager'
    when 'Herbst & Übergang'
      assign erlaubt = 'neu,damen,herren,kinder,jacke,pullover,stiefel,ch-lager'
    else
      assign erlaubt = ''
  endcase
-%}
{%- assign filterpaare = 'neu|✨ Neu,damen|Damen,herren|Herren,kinder|Kinder,baby|Baby,kleid|Kleider,jacke|Jacken,pullover|Pullover,hemd|Hemden,schuhe|Schuhe,sneaker|Sneaker,stiefel|Stiefel,guertel|Gürtel,taschen|Taschen,rucksack|Rucksäcke,schmuck|Schmuck,halskette|Halsketten,armband|Armbänder,ring|Ringe,uhren|Uhren,beauty|Beauty,hautpflege|Hautpflege,naegel|Nägel,elektronik|Elektronik,gadget|Gadgets,ladegeraet|Laden & Strom,gaming|Gaming,kueche|Küche,wohnen|Wohnen,aufbewahrung|Aufbewahrung,kissen|Kissen,werkzeug|Werkzeug,auto|Auto,haustier|Haustier,spielzeug|Spielzeug,sport|Sport,kostuem|Kostüme,halloween|🎃 Halloween,geschenk|Geschenkidee,ch-lager|⚡ Ab CH-Lager' | split: ',' -%}
{%- capture fchips -%}
  {%- for paar in filterpaare -%}
    {%- assign teile = paar | split: '|' -%}
    {%- assign t = teile[0] -%}
    {%- assign tl = teile[1] | downcase | remove: '✨ ' | remove: '🎃 ' | remove: '⚡ ' -%}
    {%- assign tl_pipe = '|' | append: tl -%}
    {%- assign ok = true -%}
    {%- if erlaubt != '' -%}{%- assign erl = erlaubt | split: ',' -%}{%- unless erl contains t -%}{%- assign ok = false -%}{%- endunless -%}{%- endif -%}
    {%- if menuetitel contains tl_pipe -%}{%- assign ok = false -%}{%- endif -%}
    {%- if ok and collection.all_tags contains t -%}
      {%- assign akt = false -%}
      {%- if current_tags contains t -%}{%- assign akt = true -%}{%- endif -%}
      {%- comment -%} Mehrfach-Filter (31.08.): native Tag-URLs koennen tag1+tag2 —
        aktiver Chip entfernt NUR sich selbst, inaktiver haengt sich an die aktiven an. {%- endcomment -%}
      {%- if akt -%}
        {%- capture rest -%}{%- for ct in current_tags -%}{%- if ct != t -%}+{{ ct }}{%- endif -%}{%- endfor -%}{%- endcapture -%}
        {%- assign rest = rest | remove_first: '+' -%}
        {%- if rest == '' -%}{%- assign ziel = collection.url -%}{%- else -%}{%- assign ziel = collection.url | append: '/' | append: rest -%}{%- endif -%}
      {%- else -%}
        {%- capture plus -%}{%- for ct in current_tags -%}{{ ct }}+{%- endfor -%}{{ t }}{%- endcapture -%}
        {%- assign ziel = collection.url | append: '/' | append: plus -%}
      {%- endif -%}
      <a href="{{ ziel }}" rel="nofollow" style="white-space:nowrap;font-size:.92rem;padding:.38rem .9rem;border-radius:999px;text-decoration:none;border:1px solid {% if akt %}#2f5a3b{% else %}#9db5a3{% endif %};{% if akt %}background:#2f5a3b;color:#fff;font-weight:700;{% else %}background:#f7faf7;color:#1f3a27;font-weight:600;{% endif %}">{{ teile[1] }}{% if akt %} ✕{% endif %}</a>
    {%- endif -%}
  {%- endfor -%}
{%- endcapture -%}
{%- if fchips contains '<a' -%}
<div class="lx-chiprow" style="width:100%;max-width:min(var(--page-width,1200px),100vw);min-width:0;box-sizing:border-box;margin:0 auto;padding:.15rem 1.5rem .3rem;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;">
  <div class="lx-chipflex" style="display:flex;gap:.45rem;width:max-content;align-items:center;padding-bottom:.3rem;">
    <span style="font-size:.9rem;font-weight:700;color:#3d2f18;white-space:nowrap;">Filtern:</span>
    {{ fchips }}
  </div>
</div>
{%- endif -%}
<style>@media (min-width:750px){.lx-chiprow{overflow:visible!important}.lx-chipflex{flex-wrap:wrap!important;width:auto!important;row-gap:.45rem!important}}</style>
",
        "padding-block-start": 0,
        "padding-block-end": 0
      }
    },
    "lux_usp_coll": {
      "type": "custom-liquid",
      "settings": {
        "custom_liquid": "<style>.lx-usp{width:100%;box-sizing:border-box;max-width:var(--page-width,1200px);margin:0 auto;padding:.5rem 1.5rem}.lx-usp__reihe{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:.7rem 1.2rem;padding:.8rem 0;border-top:1px solid #ece4d6;border-bottom:1px solid #ece4d6;font-size:13px;letter-spacing:.03em;color:#2c2c2c;line-height:1.4}.lx-usp__eintrag{display:flex;align-items:center;gap:.6rem}.lx-usp__eintrag svg{flex:0 0 auto;color:#8b7355}.lx-usp__eintrag strong{font-weight:600;color:#2c2c2c}@media(max-width:749px){.lx-usp{padding:.25rem 1rem}.lx-usp__reihe{display:flex;overflow-x:auto;gap:1.4rem;padding:.55rem 0;font-size:12.5px;scrollbar-width:none;-webkit-overflow-scrolling:touch}.lx-usp__reihe::-webkit-scrollbar{display:none}.lx-usp__eintrag{flex:0 0 auto;white-space:nowrap;gap:.4rem}.lx-usp__eintrag svg{width:16px;height:16px}}</style><div class="lx-usp"><div class="lx-usp__reihe"><span class="lx-usp__eintrag"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2"/><path d="M15 18H9"/><path d="M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.624l-3.48-4.35A1 1 0 0 0 17.52 8H14"/><circle cx="17" cy="18" r="2"/><circle cx="7" cy="18" r="2"/></svg><span><strong>Gratis-Versand</strong> in der Schweiz ab CHF 50 nach Rabatt</span></span><span class="lx-usp__eintrag"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg><span><strong>30 Tage</strong> Rückgabe</span></span><span class="lx-usp__eintrag"><svg viewBox="0 0 32 32" width="20" height="20" aria-hidden="true"><rect width="32" height="32" rx="4" fill="#d52b1e"/><path fill="#fff" d="M13 6h6v